import net.neoforged.neoforge.registries.datamaps.RegisterDataMapTypesEvent;
import net.neoforged.neoforge.registries.datamaps.DataMap;
import net.neoforged.neoforge.registries.datamaps.DataMapType;
import net.neoforged.neoforge.registries.datamaps.RegistryDataMap;

NeoForge.EVENT_BUS.addListener((RegisterDataMapTypesEvent event) -> {
    DataMapType<Item, Integer> myDataMap = event.register(
        Registries.ITEM,
        new ResourceLocation(MODID, "my_data"),
        RegistryDataMap.syncable()
    );
});
